<script setup lang="ts">import type { Task } from '~/types/task'; defineProps<{ task: Task; manage?: boolean }>();</script>
<template><article class="task-card"><div class="task-card-top"><span class="company-icon tone-blue"><AppIcon name="briefcase" /></span><span class="category-label">{{ topicLabel(task.card.topic) }}</span><span v-if="task.status !== 'published'" class="badge badge-neutral">{{ taskStatusLabel(task.status) }}</span></div><h3><NuxtLink :to="manage ? `/tasks/${task.id}/edit` : `/catalog/${task.id}`">{{ task.card.title || 'Без названия' }}</NuxtLink></h3><p class="task-description">{{ task.card.need || task.description || 'Описание пока не добавлено' }}</p><div class="tag-list"><span v-if="task.card.topic" class="tag">{{ topicLabel(task.card.topic) }}</span></div><ReadinessScore :score="task.score" compact /><div class="task-card-footer"><span><span class="status-dot" />{{ task.status === 'published' ? 'Открыта для предложений' : taskStatusLabel(task.status) }}</span><NuxtLink :to="manage ? `/tasks/${task.id}/proposals` : `/catalog/${task.id}`">{{ manage ? 'Отклики' : 'Подробнее' }} <AppIcon name="arrow" :size="14" /></NuxtLink></div></article></template>
